// Some portions generated by Co-Pilot
import React from "react";
import { useTranslations } from "next-intl";

interface ClientPaginationProps {
  currentPage: number;
  totalPages: number;
  onNavigate: (page: number) => void;
}

const ClientPagination: React.FC<ClientPaginationProps> = ({
  currentPage,
  totalPages,
  onNavigate,
}) => {
  const t = useTranslations("ModernPages.common");
  if (totalPages <= 1) return null;
  const pages: (number | string)[] = [];
  if (totalPages <= 7) {
    for (let i = 1; i <= totalPages; i++) {
      pages.push(i);
    }
  } else {
    pages.push(1);
    let start = Math.max(2, currentPage - 2);
    let end = Math.min(totalPages - 1, currentPage + 2);
    if (currentPage <= 3) {
      start = 2;
      end = 5;
    }
    if (currentPage >= totalPages - 2) {
      start = totalPages - 4;
      end = totalPages - 1;
    }
    if (start > 2) pages.push("...");
    for (let i = start; i <= end; i++) pages.push(i);
    if (end < totalPages - 1) pages.push("...");
    pages.push(totalPages);
  }
  return (
    <nav className="my-6 flex flex-wrap items-center justify-center gap-3">
      <button
        disabled={currentPage === 1}
        onClick={() => onNavigate(currentPage - 1)}
        className="min-h-10 rounded-lg px-3 py-2 text-sm text-grey hover:bg-white/5 disabled:opacity-40 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink"
      >
        {t("previous")}
      </button>
      <div className="flex items-center gap-5">
        <div className="flex flex-wrap items-center justify-center gap-1 rounded-xl border border-white/10 p-1">
          {pages.map((page, idx) =>
            page === "..." ? (
              <span key={idx} className="tab-button-text mb-0">
                ...
              </span>
            ) : (
              <button
                key={idx}
                onClick={() => onNavigate(page as number)}
                aria-current={page === currentPage ? "page" : undefined}
                className={`min-h-9 min-w-8 rounded-lg px-1 text-sm hover:bg-white/5 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink ${page === currentPage ? "font-bold text-pink" : ""}`}
                disabled={page === currentPage}
              >
                {page}
              </button>
            ),
          )}
        </div>
      </div>
      <button
        disabled={currentPage === totalPages}
        onClick={() => onNavigate(currentPage + 1)}
        className="min-h-10 rounded-lg px-3 py-2 text-sm text-grey hover:bg-white/5 disabled:opacity-40 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink"
      >
        {t("next")}
      </button>
    </nav>
  );
};

export default ClientPagination;
